<?php
require 'config.php'; require_role('student'); require_once 'pdf_helper.php';
$u=$_SESSION['user'];$term=selected_term($pdo);$termId=$term?(int)$term['id']:0;$current=current_term($pdo);$isCurrent=$current&&$term&&(int)$current['id']===$termId;
if($isCurrent){$q=$pdo->prepare("SELECT s.code,s.name,s.units,COALESCE(f.name,'Assigned Faculty') teacher,'In Progress' grade,'Current Enrollment' remarks FROM enrollments e JOIN subjects s ON s.id=e.subject_id LEFT JOIN subject_offerings o ON o.id=e.offering_id LEFT JOIN users f ON f.id=o.faculty_id WHERE e.student_id=? AND e.term_id=? ORDER BY s.code");$q->execute([$u['id'],$termId]);}else{$q=$pdo->prepare("SELECT s.code,s.name,s.units,r.teacher,r.grade,r.remarks FROM academic_records r JOIN subjects s ON s.id=r.subject_id WHERE r.user_id=? AND r.term_id=? ORDER BY s.code");$q->execute([$u['id'],$termId]);}$rows=$q->fetchAll();
$pdf=new ETW_PDF();$pdf->addPage();$pdf->setFill(0.06,0.17,0.42);$pdf->rect(0,744,612,48,true);$pdf->logo(36,660,58,68);$pdf->setFill(0.08,0.12,0.22);$pdf->text(36,635,'ACADEMIC RECORDS',18,true);$pdf->text(36,617,'ETW – NU Baliwag Online Management System',9,false);$y=585;$meta=[['Academic Term',$term['label']??'Academic Term'],['Student',$u['name']],['Student ID',$u['student_id']?:'—']];foreach($meta as $m){$pdf->text(36,$y,$m[0].':',9,true);$pdf->text(145,$y,$m[1],9,false);$y-=18;}$y-=8;$pdf->setFill(0.94,0.96,0.98);$pdf->rect(36,$y-18,540,26,true);$pdf->setFill(0.08,0.12,0.22);$cols=[36,250,300,410,490];$heads=['Subject','Units','Teacher','Grade','Status'];foreach($heads as $i=>$h)$pdf->text($cols[$i]+4,$y-8,$h,8,true);$y-=38;foreach($rows as $r){if($y<95){$pdf->addPage();$y=735;$pdf->setFill(0.08,0.12,0.22);$pdf->text(36,755,'ACADEMIC RECORDS — CONTINUED',12,true);$y-=28;}$vals=[$r['code'].' — '.$r['name'],(string)$r['units'],$r['teacher']?:'Assigned Faculty',(string)$r['grade'],(string)$r['remarks']];$wrap=[];foreach($vals as $i=>$v)$wrap[$i]=etw_pdf_wrap($v,[28,6,18,10,18][$i]);$h=max(20,max(array_map('count',$wrap))*10+6);$pdf->setStroke(.82,.85,.9);$pdf->line(36,$y-$h,576,$y-$h);foreach($wrap as $i=>$lines)foreach($lines as $j=>$line)$pdf->text($cols[$i]+4,$y-10-($j*10),$line,7,false);$y-=$h;}$pdf->setFill(.08,.12,.22);$pdf->text(36,max(55,$y-18),'Prototype academic record generated by ETW – NU Baliwag Online Management System.',7,false);$filename='ETW_Academic_Records_'.preg_replace('/[^A-Za-z0-9_-]/','_',($term['term_key']??'term')).'.pdf';$out=$pdf->output();header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.strlen($out));echo $out;exit;
